const listArtifactNodeIDs = `-- name: ListArtifactNodeIDs :many
SELECT node_id
FROM foghorn.artifact_nodes
WHERE artifact_hash = $1
  AND NOT is_orphaned
`

func (q *Queries) ListArtifactNodeIDs(ctx context.Context, artifactHash string) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, listArtifactNodeIDs, artifactHash)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var node_id string
		if err := rows.Scan(&node_id); err != nil {
			return nil, err
		}
		items = append(items, node_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

